mapper.sql:
  ${params.sqlMap.default}
and  owi.is_deleted = FALSE
  AND owid.is_deleted = FALSE


      ${params.permissionSql}

  ORDER BY


          ${item.field} ${item.sort}


  owi.create_time DESC

mapper.select:
SELECT g.id,T.source_code, G.sku_no, G.platform_sku_no, T.to_warehouse_name, G.receive_qty, TO_CHAR( G.receive_time, 'YYYY-MM-DD' ) receive_time FROM overseas_warehouse_inbound T LEFT JOIN overseas_warehouse_inbound_detail G ON T.is_deleted = 'f' AND G.is_deleted = 'f'
AND g.receive_time >= #{params.receiveDateList[0]} and (#{params.receiveDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > g.receive_time
AND t.to_warehouse_name = #{params.toWarehouseName}
